  port: 4000,
  hostname: '0.0.0.0',
  hound,
  management,
  auth: 'my-secret-token',
  cors: 'https://dashboard.example.com', // or true for any origin
  maxBodyBytes: 1_048_576, // default 1 MiB; oversized bodies get 413
});

