import { generateClient } from 'hound/';

// Run once (e.g. as part of deno task codegen)
const here = new URL('.', import.meta.url).pathname;
await generateClient({ outputDir: '../gen' }, here);

import { HoundClient } from './gen/hound-client.ts';

const client = new HoundClient('http://localhost:4000', {
  auth: Deno.env.get('HOUND_TOKEN'),
});

// Typed against HoundJobMap
await client.emit('email.send', { to: 'leo@example.com' });
await client.emitBatch([{ event: 'email.send', data: { to: 'a@b.c' } }]);

// Blocking — resolves on completion, throws on failure or timeout
await client.emitAndWait('report.build', { id: 7 }, { timeoutMs: 15_000 });

// Live job-finished events over SSE; returns an unsubscribe fn
const unsub = client.onJobFinished((e) => {
  console.log(e.jobId, e.status);
}, { queue: 'payments' });
